import { readFileSync, readdirSync } from "node:fs";
import { join, relative } from "node:path";
import { Kind, parse, type OperationDefinitionNode } from "graphql";
import { describe, expect, it } from "vitest";
import * as definitions from "@/graphql/definitions";

/**
 * `definitions.ts` is generated by `yarn codegen` from the `.graphql` files,
 * but nothing rebuilds it on its own. A `.graphql` edit committed without a
 * regeneration ships the old operation: the Overview's balances once kept
 * `conversion: "at_value"` after the source read `$marketConversion`, so
 * "Converted to USD" never reached them. Every operation the sources define
 * must be the one the generated module exports.
 */
const SRC = join(__dirname, "../..");

function graphqlFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return graphqlFiles(path);
    return entry.name.endsWith(".graphql") ? [path] : [];
  });
}

// Codegen prints the AST without locations and without empty lists.
function normalize(node: unknown): unknown {
  return JSON.parse(
    JSON.stringify(node, (key, value) =>
      key === "loc" || (Array.isArray(value) && value.length === 0)
        ? undefined
        : value,
    ),
  );
}

const operations = graphqlFiles(SRC).flatMap((file) =>
  parse(readFileSync(file, "utf8"))
    .definitions.filter(
      (node): node is OperationDefinitionNode =>
        node.kind === Kind.OPERATION_DEFINITION && Boolean(node.name),
    )
    .map((node) => ({ file: relative(SRC, file), node })),
);

describe("generated GraphQL definitions", () => {
  it("finds the operations", () => {
    expect(operations.length).toBeGreaterThan(50);
  });

  it.each(operations.map(({ file, node }) => [node.name!.value, file, node]))(
    "%s (%s) matches its source",
    (name, _file, node) => {
      const exported = (definitions as Record<string, unknown>)[
        `${name}Document`
      ] as { definitions: { kind: string; name?: { value: string } }[] };
      expect(exported, `${name}Document is not generated`).toBeDefined();
      const generated = exported.definitions.find(
        (definition) =>
          definition.kind === Kind.OPERATION_DEFINITION &&
          definition.name?.value === name,
      );
      expect(normalize(generated)).toEqual(normalize(node));
    },
  );
});
